-- 002: hero specs (damage type, roles, 0-3 ratings, difficulty) + new rules. Safe to re-run;
-- specs only overwrite heroes whose specs you haven't marked as reviewed.

create table if not exists applied_migrations (id text primary key, applied_at timestamptz not null default now());

alter table hero_profiles
  add column if not exists damage_type text check (damage_type in ('physical', 'magic', 'mixed')),
  add column if not exists roles text[] not null default '{}',
  add column if not exists ratings jsonb not null default '{}',
  add column if not exists difficulty smallint check (difficulty between 1 and 3),
  add column if not exists specs_reviewed boolean not null default false;

on conflict (slug) do update set damage_type = excluded.damage_type, roles = excluded.roles,
  ratings = excluded.ratings, difficulty = excluded.difficulty
  where hero_profiles.specs_reviewed = false
    and not exists (select 1 from applied_migrations where id = '004-rescale'); -- 0–3 values; skip once rescaled to 0–5

update hero_profiles set tags = array_append(tags, 'anti_heal') where slug = 'baxia' and not 'anti_heal' = any(tags);
update hero_profiles set tags = array_append(tags, 'cleanse') where slug = 'diggie' and not 'cleanse' = any(tags);

on conflict (id) do nothing;

-- Earlier discussion updates (Sun, Masha, Uranus). Idempotent.
update matchups set kind = 'soft', status = 'confirmed', why = 'Lifesteal build lets Ruby out-sustain Sun and his clones.' where counter = 'ruby' and target = 'sun';
update matchups set kind = 'soft', status = 'confirmed', why = 'Uranus regenerates HP while taking damage, so he out-sustains Masha.' where counter = 'uranus' and target = 'masha';
update matchups set kind = 'soft', status = 'confirmed', why = 'Masha''s damage scales with enemy HP and Belerick can''t heal it back.' where counter = 'masha' and target = 'belerick';
on conflict (counter, target) do nothing;
update hero_profiles set is_meta = true, ban_recommended = true, power_late = 5, ban_note = 'Top ban: extremely strong late-game split push.' where slug = 'sun';
